    public static function getImporteTotalByIds($ids = [])
    {
        try {
            if (count($ids) === 0) {
                return [];
            }

            $idsText = implode(',', $ids);

            $conn = Zend_Registry::get('conexion');
            $arr = $conn->fetchAll("
                SELECT tod.idtrabajooperarios ,SUM(tod.importecobrar) as importeacobrar
                FROM mod_logtaller.dat_trabajooperariosdetallado tod
                where tod.idtrabajooperarios IN ($idsText)
                group by tod.idtrabajooperarios
            ");

            if (count($arr)) {
                return $arr;
            } else {
                return [];
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }

